// Parse input and create software planning context
const input = $input.first().json;
const { topic, context, run_id, callback_url, lm_base } = input;

// Create software planning structure
const planningData = {
  run_id: run_id,
  topic: topic,
  context: context,
  lm_base: lm_base,
  callback_url: callback_url,
  software_twin: {
    name: `Software Twin for ${topic}`,
    version: '1.0.0',
    capabilities: ['planning', 'safety_check', 'simulation', 'judgment'],
    policies: ['safety_first', 'user_privacy', 'data_integrity']
  },
  task_spec: {
    name: `Task: ${topic}`,
    description: context,
    actions: [
      {
        name: 'plan',
        type: 'planning',
        parameters: { topic: topic, context: context }
      },
      {
        name: 'safety_check',
        type: 'safety',
        parameters: { topic: topic }
      },
      {
        name: 'simulate',
        type: 'simulation',
        parameters: { topic: topic }
      },
      {
        name: 'judge',
        type: 'judgment',
        parameters: { topic: topic }
      }
    ]
  }
};

return {
  json: planningData
};

