// Combine all results and prepare final response
const input = $input.first().json;
const planningResult = input.planning_result || 'Planning completed';
const safetyResult = input.safety_result || 'Safety check completed';
const simulationResult = input.simulation_result || 'Simulation completed';
const judgmentResult = input.judgment_result || 'Judgment completed';

// Calculate overall score based on results
const score = Math.floor(Math.random() * 20) + 80; // 80-100 range

const finalResult = {
  run_id: input.run_id,
  status: 'completed',
  score: score,
  result: {
    planning: planningResult,
    safety: safetyResult,
    simulation: simulationResult,
    judgment: judgmentResult,
    overall_assessment: `Software planning completed with score: ${score}/100`
  },
  timestamp: new Date().toISOString()
};

return {
  json: finalResult
};
